const root=import.meta.url,ROWS=[{path:'./assets/s1-widened-lane-plate.png',sha:'1d61a5f9f7658b34fba5027cb6020856ff176eaa7e958c78b728fb301775c9fb',xy:[2525,1070],size:[150,320]},{path:'./assets/s1-stone-post-foreground.png',sha:'c6adcd68fc92c1e3933f0e85886c5490b9c889ee068850680ddef92da3cd9525',xy:[2878,1405],size:[35,68]}],sha=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),v=>v.toString(16).padStart(2,'0')).join('');
/** Selected limited plate + original-pixel foreground. No support/movement authority. */
export async function loadApproachDecoration({fetcher=fetch,decode=b=>createImageBitmap(new Blob([b])),signal,canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}={}){
 let closed=false,matte=null;const images=[];const check=()=>{if(closed||signal?.aborted)throw Error('WETLAND_APPROACH_ART_CLOSED')};const dispose=()=>{if(closed)return;closed=true;matte=null;let first;for(const im of images.splice(0))try{im.close?.()}catch(e){first??=e}if(first)throw first};
 try{for(const row of ROWS){check();const r=await fetcher(new URL(row.path,root),{signal});if(!r.ok)throw Error('WETLAND_APPROACH_ART_MISSING');const b=new Uint8Array(await r.arrayBuffer());check();if(await sha(b)!==row.sha)throw Error('WETLAND_APPROACH_ART_PIN');check();const image=await decode(b);images.push(image);check();if(image.width!==row.size[0]||image.height!==row.size[1])throw Error('WETLAND_APPROACH_ART_SIZE')}const c=canvasFactory(35,68);try{const g=c.getContext('2d');g.drawImage(images[1],0,0);const rgba=g.getImageData(0,0,35,68).data;matte=Uint8Array.from({length:35*68},(_,i)=>rgba[i*4+3])}finally{c.width=c.height=1}check();return Object.freeze({drawPlate(ctx,camera){check();ctx.drawImage(images[0],2525-camera[0],1070-camera[1])},drawForeground(ctx,camera,foot){check();if(foot[1]<1471)ctx.drawImage(images[1],2878-camera[0],1405-camera[1])},extraForegroundAlpha(wx,wy,foot){check();const x=wx-2878,y=wy-1405;return foot[1]<1471&&Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&x<35&&y>=0&&y<68?matte[y*35+x]/255:0},dispose})}catch(e){try{dispose()}catch{}throw e}
}
